import { setupWorker } from 'msw/browser';
import { handlers } from './handlers';

/**
 * Service-worker MSW setup for the opt-in browser mock mode
 * (`NEXT_PUBLIC_API_MOCKING=enabled`). Started by `MockGate`; the worker
 * script itself (`public/mockServiceWorker.js`) is generated by the operator
 * with `pnpm dlx msw init apps/web/public/` and is never hand-written.
 */
export const worker = setupWorker(...handlers);
